insert into hobiday_editorial_payload values ('{"checked_at":"2026-09-09","operator_id":"5a0ad6a0-b07e-4cf8-973c-a14133668558","news":[{"id":"08746754-0cf8-4020-9cdc-10fe7cbeb9f0","external_id":"curated:kaf:news-253","title":"대한산악연맹·웰튼병원, 클라이밍 선수 의료지원 협약","summary":"대한산악연맹이 웰튼병원을 공식지정병원으로 두고, 스포츠클라이밍과 아이스클라이밍 선수들의 의료지원을 확대하기로 했습니다. 선수들이 훈련과 경기를 이어가는 과정에서 필요한 부상 관리와 진료를 연결하는 것이 이번 협약의 핵심입니다.\n\n지원 대상에는 연맹 소속 국가대표와 등록선수, 임직원 등이 포함됩니다. 웰튼병원은 이들의 치료와 건강관리를 지원하고, 연맹과 함께 선수 의료지원 체계를 마련할 예정입니다. 대회 당일의 대응뿐 아니라 평소 선수 관리까지 협력 범위에 포함했습니다.\n\n대회 현장에서의 대응도 협약에 담겼습니다. 연맹이 주최·주관하는 국내 대회에서 부상이나 응급상황이 발생하면 신속하게 진료와 치료로 이어질 수 있도록 협력하기로 했습니다.\n\n이번 협약은 선수 육성을 훈련 프로그램과 의료지원으로 함께 뒷받침한다는 점에서 의미가 있습니다. 연맹은 안정적인 훈련 환경 조성과 선수들의 경기력 향상에 도움이 될 것으로 기대하고 있습니다. 구체적인 협약 내용과 지원 범위는 아래 연맹 발표에서 확인할 수 있습니다.","url":"https://kaf.or.kr/news_04/253","source":"대한산악연맹","published_at":"2026-09-07T05:42:15+00:00","image_url":"https://hobiday-eight.vercel.app/images/news/medical-support-v1.webp","image_alt":"클라이머의 어깨 상태를 확인하는 의료지원 일러스트"},{"id":"adc2135d-0064-46bf-b51d-79cbce303442","external_id":"curated:worldclimbing:koper-2026-results","title":"서채현, 코페르 리드 동메달…출전 5개 대회 연속 메달","summary":"서채현이 슬로베니아 코페르에서 열린 월드 클라이밍 시리즈 리드 경기에서 동메달을 추가했습니다. 결승 기록은 32+입니다. 이번 결과로 2026년 자신이 출전한 시리즈 5개 대회에서 모두 메달을 획득하며 꾸준한 흐름을 이어갔습니다.\n\n여자 결승에서는 같은 높이까지 오른 선수들의 순위가 준결승 성적으로 갈렸습니다. 미국의 애니 샌더스 역시 32+를 기록했지만, 이전 라운드 성적을 비교하는 카운트백에 따라 서채현이 3위, 샌더스가 4위에 올랐습니다. 한국의 김채영은 첫 결승 무대에서 13+로 8위를 기록했습니다.\n\n우승은 홈 관중 앞에 나선 야냐 가른브렛이 차지했습니다. 등반 도중 미끄러지는 순간을 버텨낸 뒤 42+까지 올라 코페르에서 네 번 연속 금메달을 획득했습니다. 미국의 브룩 라바투는 33으로 은메달을 받았습니다.\n\n남자부에서는 일본의 스즈키 네오가 33+로 우승하며 시즌 세 번째 금메달을 거머쥐었습니다. 한국의 이도현은 6위, 시리즈 첫 출전에서 결승까지 오른 정찬진은 8위를 기록했습니다. 서채현의 연속 메달과 함께 한국 선수들의 결승 진출이 이어진 대회였습니다.","url":"https://www.worldclimbing.com/events/world-climbing-series-koper-2026/news/garnbret-and-suzuki-shine-in-slovenia","source":"World Climbing","published_at":"2026-09-05T00:00:00+00:00","image_url":"https://hobiday-eight.vercel.app/images/news/koper-bronze-v1.webp","image_alt":"리드 등반과 동메달을 표현한 일러스트"},{"id":"3c59bea2-81a2-42b3-b721-b2de91b75361","external_id":"curated:worldclimbing:laval-2026-lead","title":"히네스 로페스·맥니스, 라발 유럽선수권 리드 우승","summary":"프랑스 라발에서 열린 유럽선수권 마지막 날, 남녀 리드 우승자가 결정됐습니다. 남자부는 스페인의 알베르토 히네스 로페스, 여자부는 영국의 에린 맥니스가 정상에 올랐습니다. 두 결승 모두 마지막 등반에서 우승의 향방이 갈렸습니다.\n\n남자 결승에서는 첫 순서로 등반한 이탈리아의 조반니 플라치가 먼저 높은 기록을 세웠습니다. 이를 넘어선 선수는 마지막으로 출전한 히네스 로페스였습니다. 그는 40+로 우승하며 7월 샤모니 시리즈 우승에 이어 국제대회 금메달을 추가했습니다. 플라치는 첫 국제대회 메달인 은메달, 프랑스의 샘 아베주는 33+로 동메달을 받았습니다.\n\n여자부 맥니스는 예선부터 이어진 좋은 흐름을 결승까지 유지했습니다. 제한시간이 3초도 남지 않은 상황에서 마지막 홀드를 잡고 체인에 클립하며 완등했습니다. 벨기에의 엘로이즈 두몽이 52로 2위, 슬로베니아의 루츠카 라코베츠가 3위에 올랐습니다. 맥니스에게는 첫 성인 유럽선수권 타이틀입니다.\n\n라발은 유럽 리드 시리즈의 마지막 일정이기도 했습니다. 시즌 종합 순위에서는 여자부 아니카 도이블러, 남자부 조르디 폴레스가 1위를 차지했습니다. 이번 대회 우승과 시즌 종합 순위는 별도로 집계되며, 공식 발표에서 두 결과를 함께 확인할 수 있습니다.","url":"https://www.worldclimbing.com/events/world-climbing-europe-championship-laval-2026/news/gines-lopez-goes-back-to-back-mcneice-breaks-through-in-laval","source":"World Climbing","published_at":"2026-09-03T00:00:00+00:00","image_url":"https://hobiday-eight.vercel.app/images/news/laval-lead-v1.webp","image_alt":"리드 완등과 우승을 표현한 일러스트"},{"id":"f9bc2db1-2522-49ec-b92a-9ce5743ff644","external_id":"curated:worldclimbing:laval-2026-para","title":"라발 유럽 파라클라이밍 선수권, 독일 금메달 4개","summary":"8월 28~29일 프랑스 라발에서 유럽 파라클라이밍 선수권이 열렸습니다. 총 19개 경기 등급에서 메달 주인공이 가려졌으며, 독일이 금메달 4개를 포함한 9개의 메달로 국가별 메달 순위 1위에 올랐습니다.\n\n이번 유럽선수권은 라발에서 함께 열린 월드 파라클라이밍 시리즈 경기 결과를 바탕으로 순위를 정했습니다. 유럽 선수들은 한 대회에서 국제 시리즈 포인트와 유럽선수권 타이틀을 동시에 겨뤘습니다. 따라서 유럽선수권 순위는 전체 시리즈 성적과 구분해 확인해야 합니다.\n\n독일은 금 4·은 2·동 3개를 획득했습니다. 프랑스는 금 3·은 4·동 1개, 스페인은 금 3·은 2·동 3개로 각각 총 8개의 메달을 받았습니다. 공식 발표에는 19개 등급의 입상 선수와 국가별 집계가 함께 실려 있습니다.\n\n국내에서 이어질 국제대회 일정도 발표됐습니다. 연맹 발표 기준 다음 파라 시리즈는 10월 29~30일 한국 군산, 11월 5~6일 일본 후쿠오카에서 열릴 예정입니다. 라발의 등급별 결과와 후속 일정은 아래 공식 발표에서 확인할 수 있습니다.","url":"https://www.worldclimbing.com/events/world-climbing-europe-para-championship-laval-2026/news/every-medallist-at-the-world-climbing-europe-para-championship-laval-2026","source":"World Climbing","published_at":"2026-09-03T00:00:00+00:00","image_url":"https://hobiday-eight.vercel.app/images/news/laval-para-v1.webp","image_alt":"의족을 착용한 선수가 등반하는 파라클라이밍 일러스트"},{"id":"5e62864b-bbe4-4dde-b802-4e23aa2914cf","external_id":"curated:kaf:game-366","title":"2026 아시아유스선수권, 연령·종목별 공식 결과 공개","summary":"대한산악연맹이 2026 아시아유스선수권대회의 공식 결과 자료를 공개했습니다. 이번 공지는 경기 내용을 서술한 기사 대신, 연령과 종목에 따라 나뉜 PDF 결과표를 모아 제공하는 형태입니다. 관심 있는 부문의 자료를 선택해 확인할 수 있습니다.\n\n자료는 U17과 U19로 나뉘며, 각 연령대 안에서 남녀 리드·볼더·스피드 결과가 별도로 제공됩니다. 스피드 릴레이는 경기 결과와 참가 명단 파일이 함께 게시됐습니다. 연령대와 종목별로 순위가 나뉘므로, 해당 조건에 맞는 파일을 확인해야 합니다.\n\n볼더링 결과는 원문 첨부파일의 ‘U17 볼더_남·여’ 또는 ‘U19 볼더_남·여’에서 볼 수 있습니다. 원하는 연령대와 성별의 파일을 선택하면 해당 부문의 결과표로 바로 이동할 수 있습니다.\n\n하비데이는 이번 공지에서 제공하는 자료의 구성을 정리했습니다. 선수별 순위와 세부 기록은 아래 연맹 공지에 첨부된 공식 결과표를 기준으로 확인할 수 있습니다. 리드와 스피드 결과 역시 같은 공지에서 종목별로 열람할 수 있습니다.","url":"https://kaf.or.kr/game_31/366","source":"대한산악연맹","published_at":"2026-08-30T10:51:06+00:00","image_url":"https://hobiday-eight.vercel.app/images/news/asian-youth-v1.webp","image_alt":"유스 대회 결과표와 클라이밍 장비 일러스트"},{"id":"b1ec9139-3fa5-448b-b789-f0384e2d545e","external_id":"curated:kaf:news-250","title":"스포츠클라이밍 후보선수, 여름 집중훈련 마무리","summary":"스포츠클라이밍 후보선수들이 8월 8~21일 하계합숙훈련을 진행했습니다. 훈련 장소는 디스커버리클라이밍스퀘어 ICN과 허브클라이밍으로, 선수들은 종목과 훈련 방향에 따라 두 곳으로 나뉘어 훈련했습니다.\n\n프로그램에는 스피드·리드·볼더 종목별 기술 연습뿐 아니라 기초체력, 웨이트, 기능훈련이 함께 포함됐습니다. 훈련 전 워밍업과 컨디셔닝부터 훈련 뒤 쿨다운과 스트레칭까지 이어지는 구성으로, 등반 기술과 신체 준비 과정을 함께 다뤘습니다.\n\n합숙 기간에는 휴식일과 개인훈련 시간을 별도로 마련했습니다. 선수들이 부족한 부분을 보완하고 회복할 수 있도록 운영했으며, 훈련 뒤에도 개인별 몸 상태와 근골격계 특이사항, 상처 등을 확인하며 컨디셔닝을 이어갔다고 연맹은 설명했습니다.\n\n이번 훈련의 목표는 후보선수들의 종목별 전문성과 실전 경쟁력을 높이는 데 있습니다. 연맹은 선수들이 향후 국내외 대회에서 좋은 경기력을 발휘할 수 있도록 체계적인 훈련 지원을 이어갈 계획이라고 밝혔습니다. 훈련 구성과 현장 소식은 아래 연맹 발표에서 확인할 수 있습니다.","url":"https://kaf.or.kr/news_04/250","source":"대한산악연맹","published_at":"2026-08-27T00:58:00+00:00","image_url":"https://hobiday-eight.vercel.app/images/news/summer-training-v1.webp","image_alt":"암장에서 함께 훈련하는 클라이머 일러스트"}]}'::jsonb);

do $$
declare payload jsonb; expected int; matched int;
begin
  select value into payload from hobiday_editorial_payload;
  if not exists (select 1 from public.profiles where id = (payload->>'operator_id')::uuid and nickname = '운영팀') then
    raise exception 'Expected 운영팀 profile is missing; no content was changed';
  end if;
  expected := jsonb_array_length(payload->'news');
  select count(*) into matched
    from jsonb_to_recordset(payload->'news') as n(id uuid, external_id text, url text)
    join public.community_articles a on a.id = n.id and a.external_id = n.external_id and a.url = n.url and a.kind = 'news';
  if matched <> expected then
    raise exception 'Published news differs from the reviewed source set; no content was changed';
  end if;
end $$;

update public.community_articles a
   set title = n.title, summary = n.summary, image_url = n.image_url, updated_at = now()
  from hobiday_editorial_payload e,
       jsonb_to_recordset(e.value->'news') as n(id uuid, title text, summary text, image_url text)
 where a.id = n.id and (a.title is distinct from n.title or a.summary is distinct from n.summary or a.image_url is distinct from n.image_url);

-- Existing gear posts are preserved while the section is temporarily hidden.
commit;
